fn scrollable_style(
    _theme: &Theme,
    status: iced::widget::scrollable::Status,
) -> iced::widget::scrollable::Style {
    use iced::widget::scrollable::{Rail, Scroller, Status, Style};
    let (red, green, blue) = accent_rgb();
    let scroller_color = match status {
        Status::Dragged { .. } => Color::from_rgba8(red, green, blue, 0.78),
        Status::Hovered { .. } => Color::from_rgba8(0xc9, 0xc1, 0xd6, 0.55),
        Status::Active { .. } => Color::from_rgba8(0x9c, 0x93, 0xa8, 0.24),
    };
    let rail = Rail {
        background: None,
        border: Border::default(),
        scroller: Scroller {
            background: scroller_color.into(),
            border: Border {
                color: Color::TRANSPARENT,
                width: 0.0,
                radius: 5.0.into(),
            },
        },
    };
    Style {
        container: container::Style::default(),
        vertical_rail: rail,
        horizontal_rail: rail,
        gap: None,
        auto_scroll: iced::widget::scrollable::AutoScroll {
            background: surface_color().into(),
            border: Border {
                color: border_color(),
                width: 1.0,
                radius: 8.0.into(),
            },
            shadow: Shadow::default(),
            icon: text_color(),
        },
    }
}

/// Consistent scrollable styling for every page and panel.
fn scrollable<'a>(
    content: impl Into<Element<'a, Message>>,
) -> iced::widget::Scrollable<'a, Message> {
    iced::widget::scrollable(content).style(scrollable_style)
}

fn artwork_style(color: Color) -> impl Fn(&Theme) -> container::Style {
    move |_| {
        container::Style::default()
            .background(color)
            .border(Border {
                color: Color::from_rgba8(0xff, 0xff, 0xff, 0.08),
                width: 1.0,
                radius: 12.0.into(),
            })
    }
}

fn input_style(_: &Theme, status: text_input::Status) -> text_input::Style {
    let focused = matches!(
        status,
        text_input::Status::Focused { .. } | text_input::Status::Hovered
    );
    text_input::Style {
        background: surface_hi_color().into(),
        border: Border {
            color: if focused {
                accent_border()
            } else {
                border_color()
            },
            width: 1.0,
            radius: 8.0.into(),
        },
        icon: muted_color(),
        placeholder: muted_color(),
        value: text_color(),
        selection: accent_soft(),
    }
}

fn select_style(_: &Theme, status: pick_list::Status) -> pick_list::Style {
    let focused = matches!(
        status,
        pick_list::Status::Hovered | pick_list::Status::Opened { .. }
    );
    pick_list::Style {
        text_color: text_color(),
        placeholder_color: muted_color(),
        handle_color: muted_color(),
        background: surface_hi_color().into(),
        border: Border {
            color: if focused {
                accent_border()
            } else {
                border_color()
            },
            width: 1.0,
            radius: 8.0.into(),
        },
    }
}

fn nav_style(active: bool) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |_theme, status| {
        let hovered = matches!(status, button::Status::Hovered | button::Status::Pressed);
        let background = if active {
            accent_soft()
        } else if hovered {
            surface_hi_color()
        } else {
            Color::TRANSPARENT
        };
        button::Style {
            background: Some(background.into()),
            text_color: if active {
                accent()
            } else if hovered {
                text_color()
            } else {
                muted_color()
            },
            border: Border {
                color: if active {
                    accent_border()
                } else {
                    Color::TRANSPARENT
                },
                width: 1.0,
                radius: 8.0.into(),
            },
            shadow: Shadow::default(),
            snap: true,
        }
    }
}

fn ghost_style(_: &Theme, status: button::Status) -> button::Style {
    let hovered = matches!(status, button::Status::Hovered | button::Status::Pressed);
    button::Style {
        background: Some(
            if hovered {
                surface_hi_color()
            } else {
                Color::TRANSPARENT
            }
            .into(),
        ),
        text_color: if hovered { text_color() } else { muted_color() },
        border: Border {
            color: Color::TRANSPARENT,
            width: 1.0,
            radius: 8.0.into(),
        },
        shadow: Shadow::default(),
        snap: true,
    }
}

fn accent_button_style(_: &Theme, status: button::Status) -> button::Style {
    let background = match status {
        button::Status::Hovered => Color::from_rgb8(0xff, 0x86, 0xd8),
        button::Status::Pressed => Color::from_rgb8(0xe6, 0x55, 0xb6),
        button::Status::Disabled => surface_hi_color(),
        button::Status::Active => accent(),
    };
    button::Style {
        background: Some(background.into()),
        text_color: if matches!(status, button::Status::Disabled) {
            muted_color()
        } else {
            bg_color()
        },
        border: Border {
            color: Color::TRANSPARENT,
            width: 0.0,
            radius: 10.0.into(),
        },
        shadow: Shadow::default(),
        snap: true,
    }
}

fn transport_button_style(
    primary: bool,
    enabled: bool,
) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |theme, status| {
        if !enabled {
            return button::Style {
                background: Some(
                    (if primary {
                        surface_hi_color()
                    } else {
                        Color::TRANSPARENT
                    })
                    .into(),
                ),
                text_color: Color::from_rgba8(0x99, 0x8f, 0xa6, 0.35),
                border: Border {
                    color: Color::TRANSPARENT,
                    width: 1.0,
                    radius: 9.0.into(),
                },
                shadow: Shadow::default(),
                snap: true,
            };
        }
        if primary {
            accent_button_style(theme, status)
        } else {
            ghost_style(theme, status)
        }
    }
}

fn tooltip_style(_: &Theme) -> container::Style {
    container::Style::default()
        .background(surface_hi_color())
        .border(Border {
            color: border_color(),
            width: 1.0,
            radius: 7.0.into(),
        })
        .shadow(Shadow::default())
}

fn seek_style(_: &Theme, status: slider::Status) -> slider::Style {
    let active = matches!(status, slider::Status::Hovered | slider::Status::Dragged);
    let played = if active {
        Color::from_rgb8(0xff, 0x86, 0xd8)
    } else {
        accent()
    };
    let remaining = if active {
        border_color()
    } else {
        surface_hi_color()
    };
    let radius = match status {
        slider::Status::Dragged => 7.0,
        slider::Status::Hovered => 6.5,
        slider::Status::Active => 6.0,
    };
    slider::Style {
        rail: slider::Rail {
            backgrounds: (played.into(), remaining.into()),
            width: 4.0,
            border: iced::border::rounded(2.0),
        },
        handle: slider::Handle {
            shape: slider::HandleShape::Circle { radius },
            background: accent().into(),
            border_width: 2.0,
            border_color: bg_color(),
        },
    }
}

fn volume_style(_: &Theme, status: slider::Status) -> slider::Style {
    let active = matches!(status, slider::Status::Hovered | slider::Status::Dragged);
    let played = if active {
        Color::from_rgb8(0xff, 0x86, 0xd8)
    } else {
        accent()
    };
    slider::Style {
        rail: slider::Rail {
            backgrounds: (played.into(), surface_hi_color().into()),
            width: 3.0,
            border: iced::border::rounded(1.5),
        },
        handle: slider::Handle {
            shape: slider::HandleShape::Circle {
                radius: if active { 5.0 } else { 4.0 },
            },
            background: accent().into(),
            border_width: 0.0,
            border_color: Color::TRANSPARENT,
        },
    }
}

fn crossfade_toggler_style(_: &Theme, status: toggler::Status) -> toggler::Style {
    let toggled = match status {
        toggler::Status::Active { is_toggled }
        | toggler::Status::Hovered { is_toggled }
        | toggler::Status::Disabled { is_toggled } => is_toggled,
    };
    toggler::Style {
        background: if toggled {
            accent_soft()
        } else {
            surface_hi_color()
        }
        .into(),
        background_border_width: 1.0,
        background_border_color: if toggled {
            accent_border()
        } else {
            border_color()
        },
        foreground: if toggled { accent() } else { muted_color() }.into(),
        foreground_border_width: 0.0,
        foreground_border_color: Color::TRANSPARENT,
        text_color: Some(text_color()),
        border_radius: Some(12.0.into()),
        padding_ratio: 0.16,
    }
}

fn danger_button_style(_: &Theme, status: button::Status) -> button::Style {
    let hovered = matches!(status, button::Status::Hovered | button::Status::Pressed);
    button::Style {
        background: Some(
            if hovered {
                Color::from_rgba8(0xff, 0x78, 0x8c, 0.18)
            } else {
                Color::TRANSPARENT
            }
            .into(),
        ),
        text_color: DANGER,
        border: Border {
            color: Color::from_rgba8(0xff, 0x78, 0x8c, 0.45),
            width: 1.0,
            radius: 8.0.into(),
        },
        shadow: Shadow::default(),
        snap: true,
    }
}

fn track_row_style(
    checked: bool,
    focused: bool,
    current: bool,
) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |_theme, status| {
        let hovered = matches!(status, button::Status::Hovered | button::Status::Pressed);
        let background = if checked {
            accent_soft()
        } else if hovered {
            surface_hi_color()
        } else if focused {
            surface_color()
        } else {
            Color::TRANSPARENT
        };
        button::Style {
            background: Some(background.into()),
            text_color: text_color(),
            border: Border {
                color: if checked || current {
                    accent_border()
                } else if focused {
                    border_color()
                } else {
                    Color::TRANSPARENT
                },
                width: 1.0,
                radius: 8.0.into(),
            },
            shadow: Shadow::default(),
            snap: true,
        }
    }
}

fn queue_gap_style(active: bool) -> impl Fn(&Theme) -> container::Style {
    move |_theme| {
        let color = if active { accent() } else { Color::TRANSPARENT };
        container::Style::default()
            .background(color)
            .border(Border {
                color,
                width: 0.0,
                radius: 1.0.into(),
            })
    }
}

fn queue_gap_line<'a>(active: bool) -> Element<'a, Message> {
    container(iced::widget::Space::new().width(Length::Fill))
        .width(Length::Fill)
        .height(Length::Fixed(2.0))
        .style(queue_gap_style(active))
        .into()
}

fn group_style(_: &Theme, status: button::Status) -> button::Style {
    let hovered = matches!(status, button::Status::Hovered | button::Status::Pressed);
    button::Style {
        background: Some(
            (if hovered {
                surface_hi_color()
            } else {
                surface_color()
            })
            .into(),
        ),
        text_color: text_color(),
        border: Border {
            color: if hovered {
                accent_border()
            } else {
                border_color()
            },
            width: 1.0,
            radius: 10.0.into(),
        },
        shadow: Shadow::default(),
        snap: true,
    }
}

use flux_app::{WaveformScope as FlowScope, waveform_sample as scope_sample};

struct FlowOscilloscope<'a> {
    samples: &'a [f32],
    height: f32,
}

impl<Message, Theme, R> Widget<Message, Theme, R> for FlowOscilloscope<'_>
where
    R: RendererTrait,
{
    fn size(&self) -> iced::Size<Length> {
        iced::Size::new(Length::Fill, Length::Fixed(self.height))
    }

    fn layout(&mut self, _tree: &mut Tree, _renderer: &R, limits: &layout::Limits) -> layout::Node {
        layout::atomic(limits, Length::Fill, Length::Fixed(self.height))
    }

    fn draw(
        &self,
        _tree: &Tree,
        renderer: &mut R,
        _theme: &Theme,
        _style: &renderer::Style,
        layout: Layout<'_>,
        _cursor: mouse::Cursor,
        _viewport: &Rectangle,
    ) {
        let bounds = layout.bounds();
        if bounds.width <= 0.0 || bounds.height <= 0.0 || self.samples.is_empty() {
            return;
        }
        renderer.fill_quad(
            Quad {
                bounds,
                border: Border {
                    color: Color::TRANSPARENT,
                    width: 0.0,
                    radius: OSC_RADIUS.into(),
                },
                shadow: Shadow {
                    color: osc_glow(),
                    offset: iced::Vector::ZERO,
                    blur_radius: 18.0,
                },
                snap: false,
            },
            OSC_BACKGROUND,
        );

        let columns = bounds.width.ceil().max(1.0) as usize;
        let center = bounds.y + bounds.height / 2.0;

        // A restrained zero line makes quiet passages and the waveform
        // envelope easier to read without competing with the signal.
        renderer.fill_quad(
            Quad {
                bounds: Rectangle {
                    x: bounds.x + 8.0,
                    y: center - 0.5,
                    width: (bounds.width - 16.0).max(0.0),
                    height: 1.0,
                },
                snap: false,
                ..Quad::default()
            },
            osc_guide(),
        );

        let mut draw_trace = |color: Color, width: f32, halo: f32| {
            let mut previous_y = center;
            for column in 0..columns {
                let t = if columns <= 1 {
                    0.0
                } else {
                    column as f32 / (columns - 1) as f32
                };
                let value = scope_sample(self.samples, t).clamp(-1.0, 1.0);
                let y = center + value * (bounds.height / 2.0);
                let top = previous_y.min(y);
                let bottom = previous_y.max(y);
                let height = (bottom - top + width + halo * 2.0).max(width);
                renderer.fill_quad(
                    Quad {
                        bounds: Rectangle {
                            x: bounds.x + column as f32 - (width - 1.0).max(0.0) / 2.0,
                            y: top - halo,
                            width,
                            height,
                        },
                        snap: false,
                        ..Quad::default()
                    },
                    color,
                );
                previous_y = y;
            }

            // Flow closes the path at the right edge with a final line
            // back to the vertical center.
            let x = bounds.x + bounds.width - width;
            let top = previous_y.min(center);
            let bottom = previous_y.max(center);
            renderer.fill_quad(
                Quad {
                    bounds: Rectangle {
                        x,
                        y: top - halo,
                        width,
                        height: (bottom - top + width + halo * 2.0).max(width),
                    },
                    snap: false,
                    ..Quad::default()
                },
                color,
            );
        };

        // A wider translucent pass gives the one-pixel Flow line a soft
        // neon halo without changing the underlying measured samples.
        // Silence (idle, paused or no audio yet) keeps only the quiet guide
        // line so the transport does not look like it is playing.
        if !self.samples.iter().all(|sample| sample.abs() < 1e-5) {
            draw_trace(osc_glow(), 3.0, 1.0);
            draw_trace(osc_color(), OSC_LINE_WIDTH, 0.0);
        }
    }
}

impl<'a, Message> From<FlowOscilloscope<'a>> for Element<'a, Message> {
    fn from(widget: FlowOscilloscope<'a>) -> Self {
        Self::new(widget)
    }
}
struct AmbientOrbs {
    energy: f32,
    low: f32,
    phase: f32,
    height: f32,
}

impl<Message, Theme, R> Widget<Message, Theme, R> for AmbientOrbs
where
    R: RendererTrait,
{
    fn size(&self) -> iced::Size<Length> {
        iced::Size::new(Length::Fill, Length::Fixed(self.height))
    }

    fn layout(&mut self, _tree: &mut Tree, _renderer: &R, limits: &layout::Limits) -> layout::Node {
        layout::atomic(limits, Length::Fill, Length::Fixed(self.height))
    }

    fn draw(
        &self,
        _tree: &Tree,
        renderer: &mut R,
        _theme: &Theme,
        _style: &renderer::Style,
        layout: Layout<'_>,
        _cursor: mouse::Cursor,
        _viewport: &Rectangle,
    ) {
        let bounds = layout.bounds();
        if bounds.width <= 0.0 || bounds.height <= 0.0 {
            return;
        }
        let (red, green, blue) = accent_rgb();
        let energy = self.energy.clamp(0.0, 1.0);
        let low = self.low.clamp(0.0, 1.0);
        for orb in 0..4 {
            let phase = self.phase + orb as f32 * 1.7;
            let x =
                bounds.x + bounds.width * (0.18 + orb as f32 * 0.22 + 0.10 * (phase * 0.63).sin());
            let y = bounds.y + bounds.height * (0.52 + 0.20 * (phase * 0.47 + orb as f32).sin());
            let radius = bounds.height
                * (0.18
                    + 0.13 * low
                    + 0.10 * (phase * 0.81 + orb as f32 * 0.4).sin().abs()
                    + 0.06 * energy);
            for ring in 0..3 {
                let ring_radius = radius * (1.0 + ring as f32 * 0.42);
                let alpha = (0.10 + energy * 0.18) / (ring as f32 + 1.0);
                renderer.fill_quad(
                    Quad {
                        bounds: Rectangle {
                            x: x - ring_radius,
                            y: y - ring_radius,
                            width: ring_radius * 2.0,
                            height: ring_radius * 2.0,
                        },
                        border: Border {
                            color: Color::TRANSPARENT,
                            width: 0.0,
                            radius: ring_radius.into(),
                        },
                        shadow: Shadow::default(),
                        snap: false,
                    },
                    Color::from_rgba8(red, green, blue, alpha),
                );
            }
        }
    }
}

impl<'a, Message> From<AmbientOrbs> for Element<'a, Message> {
    fn from(widget: AmbientOrbs) -> Self {
        Self::new(widget)
    }
}

struct PixelWave<'a> {
    samples: &'a [f32],
    energy: f32,
    phase: f32,
    height: f32,
}

impl<Message, Theme, R> Widget<Message, Theme, R> for PixelWave<'_>
where
    R: RendererTrait,
{
    fn size(&self) -> iced::Size<Length> {
        iced::Size::new(Length::Fill, Length::Fixed(self.height))
    }

    fn layout(&mut self, _tree: &mut Tree, _renderer: &R, limits: &layout::Limits) -> layout::Node {
        layout::atomic(limits, Length::Fill, Length::Fixed(self.height))
    }

    fn draw(
        &self,
        _tree: &Tree,
        renderer: &mut R,
        _theme: &Theme,
        _style: &renderer::Style,
        layout: Layout<'_>,
        _cursor: mouse::Cursor,
        _viewport: &Rectangle,
    ) {
        let bounds = layout.bounds();
        if bounds.width <= 0.0 || bounds.height <= 0.0 || self.samples.is_empty() {
            return;
        }
        let (red, green, blue) = accent_rgb();
        let columns = (bounds.width / 6.0).floor().max(8.0) as usize;
        let rows = (bounds.height / 4.0).floor().max(4.0) as usize;
        let cell = (bounds.width / columns as f32).min(bounds.height / rows as f32);
        let gap = (cell * 0.18).max(0.8);
        let energy = self.energy.clamp(0.0, 1.0);
        let center = bounds.y + bounds.height * 0.5;
        for column in 0..columns {
            let t = if columns <= 1 {
                0.0
            } else {
                column as f32 / (columns - 1) as f32
            };
            let sample = scope_sample(self.samples, t).clamp(-1.0, 1.0);
            let wobble = (self.phase * 0.8 + t * std::f32::consts::TAU * 1.3).sin() * 0.08;
            let amplitude = (sample.abs() * (0.55 + energy * 0.45) + wobble).abs();
            let quantized = ((amplitude * rows as f32 * 2.0).round() as usize).clamp(0, rows);
            if quantized == 0 {
                continue;
            }
            let alpha = 0.16 + 0.55 * amplitude.min(1.0);
            let color = Color::from_rgba8(red, green, blue, alpha);
            let x = bounds.x + column as f32 * cell;
            for layer in 0..2 {
                let direction = if layer == 0 { -1.0 } else { 1.0 };
                let y = center + direction * (quantized as f32 * cell * 0.5);
                let y = y.clamp(bounds.y, bounds.y + bounds.height - cell);
                renderer.fill_quad(
                    Quad {
                        bounds: Rectangle {
                            x,
                            y,
                            width: (cell - gap).max(1.0),
                            height: (cell - gap).max(1.0),
                        },
                        border: Border {
                            color: Color::TRANSPARENT,
                            width: 0.0,
                            radius: (cell * 0.22).into(),
                        },
                        shadow: Shadow::default(),
                        snap: false,
                    },
                    color,
                );
            }
        }
    }
}

impl<'a, Message> From<PixelWave<'a>> for Element<'a, Message> {
    fn from(widget: PixelWave<'a>) -> Self {
        Self::new(widget)
    }
}

fn global_input_events(
    event: iced::Event,
    status: iced::event::Status,
    window: window::Id,
) -> Option<Message> {
    match event {
        // Widgets that own text input report a Captured status. Global
        // shortcuts must never steal characters from a focused editor.
        iced::Event::Keyboard(iced::keyboard::Event::KeyPressed { key, modifiers, .. })
            if status == iced::event::Status::Ignored =>
        {
            Some(Message::KeyPressedIn(window, key, modifiers))
        }
        iced::Event::Mouse(mouse::Event::ButtonReleased(mouse::Button::Left)) => {
            Some(Message::QueueDragRelease)
        }
        iced::Event::Keyboard(iced::keyboard::Event::KeyReleased {
            key:
                Key::Named(Named::ArrowLeft | Named::ArrowRight | Named::ArrowUp | Named::ArrowDown),
            ..
        }) => Some(Message::SeekCommit),
        iced::Event::Window(window::Event::FileHovered(_)) => Some(Message::ImportFileHovered),
        iced::Event::Window(window::Event::FileDropped(path)) => {
            Some(Message::ImportDropPath(path))
        }
        iced::Event::Window(window::Event::FilesHoveredLeft) => Some(Message::ImportFileHoverLeft),
        iced::Event::Mouse(mouse::Event::CursorLeft) => Some(Message::QueueDragCancel),
        _ => None,
    }
}

/// Bounded time-domain features for the audio-reactive visualizers.
fn waveform_metrics(samples: &[f32]) -> (f32, f32, f32, f32) {
    if samples.is_empty() {
        return (0.0, 0.0, 0.0, 0.0);
    }
    let count = samples.len() as f32;
    let rms = (samples.iter().map(|sample| sample * sample).sum::<f32>() / count).sqrt();
    let peak = samples
        .iter()
        .fold(0.0_f32, |value, sample| value.max(sample.abs()));
    let block = (samples.len() / 64).max(1);
    let blocks = samples.chunks_exact(block).count().max(1) as f32;
    let low = samples
        .chunks_exact(block)
        .map(|chunk| chunk.iter().sum::<f32>().abs() / chunk.len().max(1) as f32)
        .sum::<f32>()
        / blocks;
    let high = samples
        .windows(2)
        .map(|pair| (pair[1] - pair[0]).abs())
        .sum::<f32>()
        / count;
    (
        rms.clamp(0.0, 1.0),
        peak.clamp(0.0, 1.0),
        low.clamp(0.0, 1.0),
        high.clamp(0.0, 1.0),
    )
}

