    #[test]
    fn dirty_track_editor_requires_explicit_discard_or_close_confirmation() {
        let dir = TempDir::new("gui-dirty-track-editor");
        let root = dir.path().join("library");
        flux_app::create_canonical_library(&root).expect("canonical");
        let source = dir.path().join("source/song.wav");
        std::fs::create_dir_all(source.parent().expect("parent")).expect("dirs");
        std::fs::write(&source, minimal_wav()).expect("source");
        let mut gui = gui(&dir);
        send(
            &mut gui,
            Message::LibInputChanged(root.display().to_string()),
        );
        send(&mut gui, Message::OpenLibraryPressed);
        gui.controller
            .import_files(std::slice::from_ref(&source), false)
            .expect("import");
        let id = gui.controller.tracks()[0].0;

        send(&mut gui, Message::EditTrack(id));
        send(
            &mut gui,
            Message::EditorTitleChanged("Unsaved title".to_owned()),
        );
        send(
            &mut gui,
            Message::KeyPressed(Key::Character("e".into()), Modifiers::default()),
        );
        assert!(
            gui.track_editor.is_some(),
            "keyboard edit must not replace a dirty editor"
        );
        send(
            &mut gui,
            Message::ImportDropPath(dir.path().join("dropped.wav")),
        );
        assert!(
            gui.track_editor.is_some(),
            "a file drop must not discard a dirty editor"
        );
        let original_view = gui.view;
        send(&mut gui, Message::SelectView(LibraryView::Artists));
        assert_eq!(
            gui.view, original_view,
            "view switching must not hide a dirty Track editor"
        );
        let artist_id = gui.controller.track_artist_id(id).expect("artist");
        send(&mut gui, Message::OpenArtist(artist_id));
        assert_eq!(gui.view, original_view);
        let other_root = dir.path().join("other-library");
        flux_app::create_canonical_library(&other_root).expect("other canonical");
        gui.lib_input = other_root.display().to_string();
        send(&mut gui, Message::OpenLibraryPressed);
        assert_eq!(
            gui.controller.canonical_root(),
            Some(
                std::fs::canonicalize(&root)
                    .expect("canonical root")
                    .as_path()
            )
        );
        assert!(
            gui.track_editor.is_some(),
            "switching libraries must not discard a dirty Track editor"
        );
        gui.lib_input = root.display().to_string();

        send(
            &mut gui,
            Message::KeyPressed(Key::Named(Named::Escape), Modifiers::default()),
        );
        assert!(gui.track_editor.is_some());
        assert!(
            gui.track_editor
                .as_ref()
                .and_then(|editor| editor.error.as_deref())
                .is_some_and(|error| error.contains("Unsaved metadata"))
        );
        send(
            &mut gui,
            Message::KeyPressed(Key::Named(Named::Escape), Modifiers::default()),
        );
        assert!(gui.track_editor.is_none());

        send(&mut gui, Message::EditTrack(id));
        send(
            &mut gui,
            Message::EditorTitleChanged("Another title".to_owned()),
        );
        let _ = gui.update(Message::WindowCloseRequested(iced::window::Id::unique()));
        assert!(!gui.closed);
        assert!(gui.close_confirm);
        assert!(gui.track_editor.is_some());
        send(
            &mut gui,
            Message::KeyPressed(Key::Named(Named::Escape), Modifiers::default()),
        );
        assert!(
            gui.track_editor.is_some(),
            "acking the close warning with Escape must not bypass the editor"
        );
        assert!(
            gui.track_editor
                .as_ref()
                .is_some_and(|editor| editor.discard_confirm)
        );
        gui.controller.shutdown();
    }

